Index: src/app/globals.css
===================================================================
--- src/app/globals.css	
+++ src/app/globals.css	
@@ -1,397 +1,408 @@
 @import "tailwindcss";

 /*
   Design system — dark-technical "beast" base.
   Palette pairs deep ink backgrounds with an electric-cyan + violet accent,
   echoing the ContextOS/Graph-Forge dashboards. WCAG AA verified on bg-base.
 */
 :root {
   /* surfaces */
   --bg-base: #07080d;        /* page background */
   --bg-surface: #0d0f17;     /* cards */
   --bg-elevated: #141826;    /* hovered / elevated */
   --border: #1f2433;
   --border-strong: #2c3346;

   /* text */
   --fg: #e9ecf5;             /* primary text — 14.8:1 on bg-base */
   --fg-muted: #9aa3b8;       /* secondary — 6.9:1 on bg-base (AA) */
   --fg-subtle: #747e99;      /* tertiary / captions — 4.7:1 on bg-base (WCAG AA) */

   /* accents */
   --accent: #38e1ff;         /* electric cyan — links, focus, graph edges */
   --accent-strong: #0fb8db;
   --violet: #a78bfa;         /* secondary accent — AI/agent motifs */
   --green: #4ade80;          /* metrics up / success */
   --amber: #fbbf24;          /* highlights */

   /* effects */
   --glow-accent: 0 0 0 1px color-mix(in oklab, var(--accent) 35%, transparent),
                  0 0 24px -4px color-mix(in oklab, var(--accent) 45%, transparent);
 }

 @theme inline {
   --color-bg-base: var(--bg-base);
   --color-bg-surface: var(--bg-surface);
   --color-bg-elevated: var(--bg-elevated);
   --color-border: var(--border);
   --color-border-strong: var(--border-strong);
   --color-fg: var(--fg);
   --color-fg-muted: var(--fg-muted);
   --color-fg-subtle: var(--fg-subtle);
   --color-accent: var(--accent);
   --color-accent-strong: var(--accent-strong);
   --color-violet: var(--violet);
   --color-green: var(--green);
   --color-amber: var(--amber);

   --font-sans: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
   --font-mono: var(--font-mono), ui-monospace, "SF Mono", monospace;

   --radius-card: 14px;
 }

 * {
   border-color: var(--border);
 }

 html {
   scroll-behavior: smooth;
   -webkit-font-smoothing: antialiased;
   /* WCAG 2.2 SC 2.4.12 Focus Not Obscured: the sticky h-14 (3.5rem) header would
      otherwise cover a focused in-page anchor target. Pad the scroll position so the
      focused element lands below the header. */
   scroll-padding-top: 3.5rem;
   /* Defensive backstop: an un-contained overflowing descendant anywhere in the tree
      (e.g. a shrink-to-fit row wider than the viewport) would otherwise widen the whole
      document and cause page-level horizontal scroll/drag on mobile. Any element that
      genuinely needs horizontal scroll must opt in locally with its own overflow-x-auto
      container (see the articles filter bar) — this rule only clips the leak, it never
      hides content that has its own scroll container. */
   overflow-x: hidden;
 }

+/* Full-height views (chat and developer) fit exactly in the viewport without page scroll */
+html[data-full-height="true"],
+html[data-full-height="true"] body {
+  height: 100dvh;
+  overflow: hidden;
+}
+
+html[data-full-height="true"] #main-content {
+  min-height: 0;
+}
+
 @media (prefers-reduced-motion: reduce) {
   html { scroll-behavior: auto; }
 }

 /*
   Hero entrance — pure CSS, runs on first paint with NO JS/hydration gate, so the
   above-the-fold hero is never invisible-then-faded-in (that caused a load flicker
   and delayed LCP). Below-the-fold sections still use the JS-gated <Reveal>.
 */
 @keyframes hero-rise {
   from { opacity: 0; transform: translateY(12px); }
   to   { opacity: 1; transform: translateY(0); }
 }
 .hero-rise {
   opacity: 0;
   animation: hero-rise 0.5s cubic-bezier(0.21, 0.47, 0.32, 0.98) forwards;
 }
 @media (prefers-reduced-motion: reduce) {
   .hero-rise { opacity: 1; animation: none; }
 }

 /* Terminal cursor — cosmetic blink; solid (no animation) under reduced-motion. */
 @keyframes terminal-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
 .terminal-cursor { animation: terminal-blink 1s steps(1) infinite; }
 @media (prefers-reduced-motion: reduce) {
   .terminal-cursor { animation: none; opacity: 1; }
 }

 /* Terminal boot — one-time fade-in of the scrollback on mount (the "boot" feel).
    Text is fully in the DOM (screen-reader-safe); this only animates opacity. */
 @keyframes terminal-boot { from { opacity: 0; } to { opacity: 1; } }
 .terminal-boot { animation: terminal-boot 0.4s ease-out; }
 @media (prefers-reduced-motion: reduce) {
   .terminal-boot { animation: none; }
 }

 /* Anvil header-orb idle — a FLUID, swirling, color-shifting Siri-style orb. The "metaball
    by blur+contrast" recipe: several conic-gradient color lobes painted on one pseudo, then
    fused by `filter: blur() contrast()` so they bleed + merge into liquid blobs (the contrast
    re-sharpens the blurred edges into rounded metaballs), with the conic `from` angle spun by
    a registered @property for the swirl, and a slow hue-rotate for the color shift — all in
    ONE filter chain (filter is a single property). PURE CSS, ZERO JS/rAF/WebGL/new-dep. COST:
    animating a @property angle is a per-frame MAIN-THREAD style-recalc + paint of the small
    ~38px pseudo (custom-property animation is NOT compositor-promoted) — negligible at this
    size and never the LCP element, but do NOT scale this recipe up while animated. The heavy
    3D orb only mounts inside the open voice surface. NOTE: NO mix-blend-mode — the conic
    layers self-fuse via overlap+contrast, which also sidesteps the WebKit backdrop-filter +
    descendant-blend glitch (bug 176830) under the header's backdrop-blur. isolation +
    overflow:hidden + translateZ(0) keep it on its own layer. Reduced-motion → a STATIC but
    still rich/fused orb (keeps blur+contrast — never `filter:none`, which would shatter the
    metaballs into hard arcs). Pre-Baseline browsers (Safari <16.4) ignore @property → the
    conic `from` is unset and the orb degrades to the solid `--accent-strong` disc + glow (a
    fine fallback, not the fused metaball). blur is tuned for the real 28px host, not a preview. */

 @property --anvil-swirl {
   syntax: "<angle>";
   inherits: false;
   initial-value: 40deg;
 }
 @property --anvil-hue {
   syntax: "<angle>";
   inherits: false;
   initial-value: 0deg;
 }

 @keyframes anvil-swirl-spin { to { --anvil-swirl: 400deg; } }
 @keyframes anvil-hue-drift { to { --anvil-hue: 360deg; } }
 @keyframes anvil-breathe {
   0%, 100% { transform: scale(1); }
   50% { transform: scale(1.06); }
 }

 .anvil-orb-idle {
   position: relative;
   isolation: isolate;          /* own stacking context (keeps the fuse off the header backdrop) */
   overflow: hidden;            /* clip the fused blobs to the orb circle */
   border-radius: 9999px;
   background: var(--accent-strong); /* base wash behind the metaballs */
   box-shadow: 0 0 12px -2px color-mix(in oklab, var(--accent) 65%, transparent);
   animation: anvil-breathe 3.6s ease-in-out infinite;
 }
 /* The fluid layer: 4 conic color lobes at distinct off-center origins + signed swirl
    multipliers, fused by blur+contrast into liquid metaballs, hue-rotated for the shift. */
 .anvil-orb-idle::before {
   content: "";
   position: absolute;
   inset: -25%;
   border-radius: 9999px;
   transform: translateZ(0);    /* promote to its own layer (Safari backdrop-root guard) */
   background:
     conic-gradient(from calc(var(--anvil-swirl) * 2)  at 32% 38%, var(--accent) 0deg, transparent 110deg),
     conic-gradient(from calc(var(--anvil-swirl) * -3) at 68% 36%, var(--violet, #a78bfa) 0deg, transparent 120deg),
     conic-gradient(from calc(var(--anvil-swirl) * 1)  at 40% 70%, color-mix(in oklab, var(--accent) 80%, white) 0deg, transparent 100deg),
     conic-gradient(from calc(var(--anvil-swirl) * -2) at 64% 66%, var(--accent-strong) 0deg, transparent 130deg);
   /* blur tuned for the REAL 28px host (~1.4px ≈ 5% of diameter) — fuses the lobes without
      washing them into a uniform smear; contrast re-sharpens into rounded metaballs. */
   filter: blur(1.4px) contrast(4.5) hue-rotate(var(--anvil-hue));
   animation:
     anvil-swirl-spin 18s linear infinite,
     anvil-hue-drift 22s linear infinite;
 }
 @media (prefers-reduced-motion: reduce) {
   .anvil-orb-idle,
   .anvil-orb-idle::before {
     animation: none;
   }
   /* Keep the fused metaballs (static): freeze the swirl at its balanced initial angle and
      KEEP blur+contrast (a one-time raster, free) + a fixed hue — never `filter: none`. */
   .anvil-orb-idle::before {
     filter: blur(1.4px) contrast(4.5) hue-rotate(0deg);
   }
 }

 body {
   background: var(--bg-base);
   color: var(--fg);
   font-family: var(--font-sans);
   /* Same backstop as html above — some mobile WebKit builds still rubber-band the body's
      own scrollable overflow even when the html root is clipped. Belt-and-suspenders only;
      the fix is containing overflow at its source (see the articles filter bar). */
   overflow-x: hidden;
   /* faint technical grid + radial accent wash */
   background-image:
     radial-gradient(60rem 40rem at 75% -10%, color-mix(in oklab, var(--violet) 9%, transparent), transparent 70%),
     radial-gradient(50rem 36rem at 5% 0%, color-mix(in oklab, var(--accent) 8%, transparent), transparent 70%),
     linear-gradient(to right, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px),
     linear-gradient(to bottom, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px);
   background-size: 100% 100%, 100% 100%, 56px 56px, 56px 56px;
   background-attachment: fixed;
 }

 /* focus-visible: keyboard nav (a11y).
    The .no-focus-ring opt-out is for elements that carry their OWN focus affordance
    (e.g. the ⌘K search row's focus-within border) — needed because this rule is
    UNLAYERED and would otherwise always beat any Tailwind utility (utilities live in
    @layer, and unlayered CSS wins the cascade regardless of specificity). */
 /* WCAG 2.2 SC 2.4.11 Focus Appearance: a 3px outline (≥2px min) with offset gives a
    focus indicator whose contrast area clears the threshold against any background. */
 :focus-visible:not(.no-focus-ring) {
   outline: 3px solid var(--accent);
   outline-offset: 2px;
   border-radius: 4px;
 }

 /* Skip-to-content link: visually hidden until focused, then the first interactive
    element so keyboard users can jump past the nav to the page content (a11y basic). */
 .skip-link {
   position: fixed;
   top: 0.5rem;
   left: 0.5rem;
   z-index: 100;
   transform: translateY(-150%);
   transition: transform 0.15s ease;
   background: var(--bg-elevated);
   color: var(--fg);
   border: 1px solid var(--accent);
   border-radius: 8px;
   padding: 0.5rem 0.875rem;
   font-size: 0.875rem;
 }
 .skip-link:focus {
   transform: translateY(0);
 }
 @media (prefers-reduced-motion: reduce) {
   .skip-link {
     transition: none;
   }
 }

 ::selection {
   background: color-mix(in oklab, var(--accent) 30%, transparent);
   color: #fff;
 }

 /* utility: subtle card */
 .card-surface {
   background: var(--bg-surface);
   border: 1px solid var(--border);
   border-radius: var(--radius-card);
 }
 .card-surface:hover {
   border-color: var(--border-strong);
   background: var(--bg-elevated);
 }

 /* utility: monospace terminal label */
 .mono-label {
   font-family: var(--font-mono);
   font-size: 0.75rem;
   letter-spacing: 0.08em;
   text-transform: uppercase;
   color: var(--accent);
 }

 /*
   View transitions — cross-fade when switching the top-level view (Classic / Chat /
   Play / Developer). Driven from setViewInternal via document.startViewTransition.
   Only `view-body` cross-fades; `site-header` is its own group and is pinned (no
   animation) so the sticky nav stays put across a switch.
 */
 /* Directional slide keyframes for view transitions (C-1 upgrade from plain cross-fade) */
 @keyframes vt-slide-in-from-right  { from { transform: translateX(6%);  opacity: 0; } to { transform: none; opacity: 1; } }
 @keyframes vt-slide-in-from-left   { from { transform: translateX(-6%); opacity: 0; } to { transform: none; opacity: 1; } }
 @keyframes vt-slide-out-to-left    { from { transform: none; opacity: 1; } to { transform: translateX(-6%); opacity: 0; } }
 @keyframes vt-slide-out-to-right   { from { transform: none; opacity: 1; } to { transform: translateX(6%);  opacity: 0; } }

 /* Forward (classic→chat etc): new view slides in from right, old slides out left */
 [data-view-dir="forward"]::view-transition-new(view-body)  {
   animation: vt-slide-in-from-right 0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
 }
 [data-view-dir="forward"]::view-transition-old(view-body)  {
   animation: vt-slide-out-to-left   0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
 }

 /* Backward (chat→classic etc): new view slides in from left, old slides out right */
 [data-view-dir="backward"]::view-transition-new(view-body) {
   animation: vt-slide-in-from-left  0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
 }
 [data-view-dir="backward"]::view-transition-old(view-body) {
   animation: vt-slide-out-to-right  0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
 }
 ::view-transition-old(site-header),
 ::view-transition-new(site-header) {
   /* Pin the persistent chrome — don't fade it with the body. */
   animation: none;
   mix-blend-mode: normal;
 }

 /* Reduced-motion kill-switch (belt-and-suspenders — JS already skips the API for
    these users; this guarantees no cross-fade even if a transition is ever started). */
 @media (prefers-reduced-motion: reduce) {
   ::view-transition-group(*),
   ::view-transition-old(*),
   ::view-transition-new(*) {
     animation: none !important;
   }
 }

 /* ── 404 glitch eyebrow ───────────────────────────────────────────────────────
    Organic text-glitch for the "// 404 :: route-not-found" label on not-found.tsx.
    Respects prefers-reduced-motion by skipping the animation entirely.             */
 @keyframes glitch-text {
   0%, 92%, 100% { transform: none; opacity: 1; }
   93%           { transform: skewX(-6deg) translateX(3px); opacity: 0.85; }
   95%           { transform: skewX(4deg) translateX(-2px); opacity: 0.9; }
   97%           { transform: skewX(-2deg) translateX(1px); opacity: 0.95; }
 }

 .glitch-eyebrow {
   animation: glitch-text 4s infinite;
 }

 @media (prefers-reduced-motion: reduce) {
   .glitch-eyebrow { animation: none; }
 }

 /* ── CSS scroll-driven reveals ───────────────────────────────────────────────
    Native animation-timeline: view() ties the animation progress to when the
    element enters the viewport scroll-timeline. No JS, no rAF, runs on the
    compositor thread. Supported: Chrome 115+, Firefox 110+, Safari 15.4+.
    Pre-Baseline browsers: animation: none fallback (static opacity:1).
    Kill-switch: prefers-reduced-motion → snap to final state immediately.    */

 @keyframes scroll-fade-up {
   from { opacity: 0; translate: 0 20px; }
   to   { opacity: 1; translate: 0 0; }
 }

 /* Base utility: fades up as the element enters the viewport. */
 .scroll-reveal {
   animation: scroll-fade-up linear both;
   animation-timeline: view();
   animation-range: entry 0% entry 35%;
 }

 /* Staggered variants for grid cards (N = 1–6, delay = N × 60ms). */
 .scroll-reveal-stagger-1 { animation-delay: 60ms;  }
 .scroll-reveal-stagger-2 { animation-delay: 120ms; }
 .scroll-reveal-stagger-3 { animation-delay: 180ms; }
 .scroll-reveal-stagger-4 { animation-delay: 240ms; }
 .scroll-reveal-stagger-5 { animation-delay: 300ms; }
 .scroll-reveal-stagger-6 { animation-delay: 360ms; }

 @media (prefers-reduced-motion: reduce) {
   .scroll-reveal,
   [class*="scroll-reveal-stagger"] {
     animation: none;
     opacity: 1;
     translate: none;
   }
 }

 /* ─────────────────────────────────────────────────────────────────────────────
    Skeleton / shimmer loading system
    Single keyframe drives the sweep; .skeleton-shimmer applies gradient + size.
    The cyan accent hint at 50% gives the "electric" quality matching the palette.
    Runs 100% on the compositor thread (only background-position changes).
    ───────────────────────────────────────────────────────────────────────────── */
 @keyframes shimmer {
   0%   { background-position: -200% center; }
   100% { background-position:  200% center; }
 }

 .skeleton-shimmer {
   background: linear-gradient(
     90deg,
     color-mix(in oklab, var(--fg-subtle)  8%, transparent)  0%,
     color-mix(in oklab, var(--fg-subtle) 18%, transparent) 38%,
     color-mix(in oklab, var(--accent)     8%, transparent) 50%,
     color-mix(in oklab, var(--fg-subtle) 18%, transparent) 62%,
     color-mix(in oklab, var(--fg-subtle)  8%, transparent) 100%
   );
   background-size: 200% 100%;
   animation: shimmer 1.8s ease-in-out infinite;
   border-radius: inherit;
 }

 @media (prefers-reduced-motion: reduce) {
   .skeleton-shimmer {
     animation: none;
     background: color-mix(in oklab, var(--fg-subtle) 10%, transparent);
   }
 }

Index: src/components/chat/chat-view.tsx
===================================================================
--- src/components/chat/chat-view.tsx	
+++ src/components/chat/chat-view.tsx	
@@ -1,186 +1,183 @@
 "use client";

 import { useState } from "react";
 import { Sparkles, Send } from "lucide-react";
 import { useChat } from "@/components/chat/use-chat";
 import { RECRUITER_CHIPS, STARTER_CHIPS } from "@/components/chat/chat-suggestions";
 import { ChatMessages } from "@/components/chat/chat-messages";
 import { MicButton } from "@/components/chat/mic-button";
 import { TalkLaunchButton } from "@/components/chat/talk-launch-button";
 import { FilePickerButton } from "@/components/chat/file-picker-button";
 import { AttachmentPreviewStrip } from "@/components/chat/attachment-preview-strip";
 import { ViewEscapeHatch } from "@/components/view-escape-hatch";
 import { profile, impactMetrics } from "@/lib/profile";

 /**
  * AI-CHAT view — a full "concierge console", not a bare chat box. Opens answer-
  * first: identity + impact strip + a persistent recruiter chip-rail so the
  * strongest-work / GenAI / impact answers are one tap. Reuses the existing Bedrock
  * backend (/api/chat -> streamWithFallback) untouched via the useChat transport.
  *
  * The escape hatch is the FIRST focusable element (never a keyboard trap). Full
  * a11y (aria-live announce-on-settle, Stop, pin-aware autoscroll) lands in 2.3.
  */
 export function ChatView() {
   const { messages, send, stop, isStreaming, pendingFiles, setPendingFiles } = useChat();
   const [input, setInput] = useState("");
   const empty = messages.length === 0;

   const onSubmit = (e: React.FormEvent) => {
     e.preventDefault();
     send(input, pendingFiles.length > 0 ? pendingFiles : undefined);
     setInput("");
     setPendingFiles([]);
   };

   const ask = (q: string) => {
     if (isStreaming) return;
     send(q, []);
     setInput("");
   };

   return (
-    // Fixed height (not min-h): the console must be a BOUNDED flex container so the
-    // transcript scrolls INTERNALLY. With only min-height the element is content-sized
-    // and unbounded, so a tall conversation grows the document and the inner
-    // overflow-y-auto never engages (the autoscroll snap then no-ops). `dvh` (not vh)
-    // keeps the composer clear of iOS Safari's address bar.
-    <main className="mx-auto flex h-[calc(100dvh-3.5rem)] w-full max-w-3xl flex-col px-6 py-6">
+    // Bounded flex container (flex-1 min-h-0): takes exact remaining viewport space
+    // below the site nav and banner so the transcript scrolls INTERNALLY without page scroll.
+    <main className="mx-auto flex flex-1 min-h-0 w-full max-w-3xl flex-col px-6 py-6">
       <div className="flex items-center justify-between gap-3">
         <ViewEscapeHatch />
         <div className="flex items-center gap-3">
           {/* Hands-free voice conversation (modal surface; null on the 5th-view surface
               or unsupported browsers). */}
           <TalkLaunchButton />
           <p className="inline-flex items-center gap-1.5 font-mono text-xs uppercase tracking-widest text-accent">
             <Sparkles size={13} aria-hidden="true" /> AI Concierge
           </p>
         </div>
       </div>

       {/* Bordered "console" panel — frames the whole conversation so it reads as a
           contained concierge terminal, not scattered elements in an empty void. */}
       {/* min-h-0 lets this flex child shrink below its content so the transcript
           (the flex-1 child below) can own the overflow instead of pushing the page. */}
       <section className="mt-4 flex min-h-0 flex-1 flex-col rounded-2xl border border-border-strong bg-bg-surface/40 p-5 shadow-xl shadow-black/20 backdrop-blur sm:p-6">
       {/* Answer-first greeting + verified impact strip (recruiter visual triage).
           min-h-0 + overflow-y-auto + shrink: on a SHORT viewport this tall block (greeting +
           6-tile metric grid) must scroll WITHIN itself rather than push the composer out of
           the bordered console (it was a rigid flex sibling, so it shoved the composer + caption
           past the section border). It collapses to nothing once a conversation starts (empty). */}
       {empty && (
         <header className="min-h-0 shrink overflow-y-auto">
           <h1 className="text-2xl font-semibold tracking-tight">
             Ask me anything about {profile.name.split(" ")[0]}&apos;s work
           </h1>
           <p className="mt-2 max-w-xl text-sm text-fg-muted">
             Grounded in real projects and production systems — GenAI, backend, and open source.
             I answer in the first person and never invent details.
           </p>
           <dl className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
             {impactMetrics.map((m) => (
               <div key={m.label + m.sub} className="rounded-xl border border-border bg-bg-surface/60 px-3 py-2.5">
                 {/* dt = term (the metric), dd = description (its value+context) */}
                 <dt className="font-mono text-lg font-semibold text-fg">{m.value}</dt>
                 <dd className="text-xs text-fg-muted">{m.label}</dd>
                 <dd className="text-[11px] text-fg-subtle">{m.sub}</dd>
               </div>
             ))}
           </dl>
         </header>
       )}

       {/* Conversation. Grows to fill; messages + a11y live region live here (2.3). */}
       <ChatMessages messages={messages} isStreaming={isStreaming} />

       {/* Persistent recruiter chip-rail — one-tap strongest-work / impact paths.
           shrink-0: never let a short viewport compress the chips into the transcript. */}
       <div className="mt-4 shrink-0">
         <div className="flex flex-wrap gap-2" role="group" aria-label="Suggested questions">
           {RECRUITER_CHIPS.map((c) => (
             <button
               key={c}
               type="button"
               onClick={() => ask(c)}
               disabled={isStreaming}
               className="rounded-full border border-border px-3 py-1.5 text-xs text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
             >
               {c}
             </button>
           ))}
         </div>
         {empty && (
           <div className="mt-2 flex flex-wrap gap-2">
             {STARTER_CHIPS.map((c) => (
               <button
                 key={c}
                 type="button"
                 onClick={() => ask(c)}
                 disabled={isStreaming}
                 className="rounded-full px-3 py-1.5 text-xs text-fg-subtle transition-colors hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
               >
                 {c}
               </button>
             ))}
           </div>
         )}
       </div>

       {/* Pending attachment previews — rendered above the composer when files are queued.
           Returns null when empty so there is no layout shift. */}
       <AttachmentPreviewStrip
         files={pendingFiles}
         onRemove={(i) => setPendingFiles((prev) => {
           const removed = prev[i];
           if (removed?.previewUrl) URL.revokeObjectURL(removed.previewUrl);
           return prev.filter((_, idx) => idx !== i);
         })}
       />

       {/* Composer. shrink-0: the input the user types in must NEVER be compressed or
