"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Mail, Rss } from "lucide-react";
import { Github, Linkedin } from "@/components/icons";
import { profile } from "@/lib/profile";
import { useView } from "@/components/view-context";

const VISIT_CACHE_KEY = "anvilry:visits:total";

/**
 * Fire-and-forget visitor counter. POSTs to /api/visit on mount (once per page load),
 * then shows the running total. Rate-limited server-side to 1 increment per IP / 30 min.
 * Gate: NEXT_PUBLIC_VISITOR_COUNTER=true (default OFF).
 *
 * localStorage fallback: seeds from cache on mount so repeat visitors see the last-known
 * count instantly, and so the badge shows a real number when Redis is unavailable (total=0).
 * Only a positive total from the API overwrites the cache — a 0 (Redis down) is ignored.
 */

display.text:
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Mail, Rss } from "lucide-react";
import { Github, Linkedin } from "@/components/icons";
import { profile } from "@/lib/profile";
import { useView } from "@/components/view-context";

const VISIT_CACHE_KEY = "anvilry:visits:total";

/**
 * Fire-and-forget visitor counter. POSTs to /api/visit on mount (once per page load),
 * then shows the running total. Rate-limited server-side to 1 increment per IP / 30 min.
 * Gate: NEXT_PUBLIC_VISITOR_COUNTER=true (default OFF).
 *
 * localStorage fallback: seeds from cache on mount so repeat visitors see the last-known
 * count instantly, and so the badge shows a real number when Redis is unavailable (total=0).
 * Only a positive total from the API overwrites the cache — a 0 (Redis down) is ignored.
 */
function VisitorBadge() {
  // Always start with null — localStorage is browser-only and must not be read during SSR.
  // Reading it in the useState initializer causes a hydration mismatch because the server
  // renders null→skeleton while the client renders cached count→real badge.
  // Seed from localStorage in useEffect (client-only, post-hydration) instead.
  const [total, setTotal] = useState<number | null>(null);

  useEffect(() => {
    // Seed from localStorage cache so repeat visitors see the last-known count
    // before the API call resolves. This setState call is intentional and safe:
    // it runs once on mount (client-only) and does not depend on any external
    // subscription — it is a one-time initialisation from a local store, which is
    // a documented exception to the set-state-in-effect heuristic.
    try {
      const cached = localStorage.getItem(VISIT_CACHE_KEY);
      if (cached !== null) setTotal(Number(cached)); // eslint-disable-line react-hooks/set-state-in-effect -- intentional: one-time localStorage seed on mount, no subscription
    } catch {
      // localStorage unavailable — stay on null (skeleton shown)
    }

    fetch("/api/visit", { method: "POST" })
      .then((r) => (r.ok ? r.json() : null))
      .then((data: { total: number; today: number } | null) => {
        if (data?.total != null && data.total > 0) {
          setTotal(data.total);
          try {
            localStorage.setItem(VISIT_CACHE_KEY, String(data.total));
          } catch {
            // localStorage blocked (private browsing / storage full) — ignore
          }
        }
        // If total === 0: Redis was unavailable. Keep the cached value (don't call setTotal).
      })
      .catch(() => {
        // Network error — cached value (already in state) stays visible
      });
  }, []);

  if (total === null) {
    return (
      <span
        className="inline-block h-3 w-28 animate-pulse rounded bg-fg-subtle/20"
        aria-hidden="true"
      />
    );
  }
  if (total === 0) return null; // No cache, no real count — hide the badge entirely

  return (
    <span className="font-mono text-xs text-fg-subtle">
      ↑ {total.toLocaleString()} engineers visited
    </span>
  );
}

// Machine-readable surfaces — the AI-crawler / agent-native artifacts. Grouped here so
// they're discoverable (previously /llms.txt + /api/resume.json existed but weren't
// linked from anywhere). On-brand for a GenAI engineer.
const MACHINE_LINKS = [
  { href: "/mcp", label: "MCP server" },
  { href: "/llms.txt", label: "llms.txt" },
  { href: "/api/resume.json", label: "resume.json" },
];

