const { chromium } = require('@playwright/test');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3000/?view=chat');
  await page.waitForSelector('text=Ask me anything about Sairam');

  const measurements = await page.evaluate(() => {
    // Apply full height styles
    document.documentElement.classList.add('h-dvh', 'overflow-hidden');
    document.body.classList.add('h-dvh', 'overflow-hidden');
    document.body.classList.remove('min-h-full');

    const mainContent = document.getElementById('main-content');
    mainContent.classList.add('min-h-0');

    const viewBody = mainContent.firstElementChild; // ViewRouter div
    viewBody.classList.add('flex', 'flex-1', 'flex-col', 'min-h-0');

    const chatMain = document.querySelectorAll('main')[1]; // ChatView main
    chatMain.classList.remove('h-[calc(100dvh-3.5rem)]');
    chatMain.classList.add('flex-1', 'min-h-0', 'h-full');

    return {
      windowInnerHeight: window.innerHeight,
      docScrollHeight: document.documentElement.scrollHeight,
      docClientHeight: document.documentElement.clientHeight,
      bodyScrollHeight: document.body.scrollHeight,
      bodyClientHeight: document.body.clientHeight,
      chatMainOffsetHeight: chatMain.offsetHeight,
      canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight
    };
  });
  console.log('1440x900 full height chat:', measurements);

  // Test scrolling with mouse wheel
  await page.mouse.wheel(0, 200);
  await page.waitForTimeout(200);
  console.log('1440 scrollY after wheel:', await page.evaluate(() => window.scrollY));

  await page.screenshot({ path: '/tmp/test_chat_fixed_1440.png' });

  // Now test 390x844
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(300);
  const m390 = await page.evaluate(() => {
    const chatMain = document.querySelectorAll('main')[1];
    return {
      windowInnerHeight: window.innerHeight,
      docScrollHeight: document.documentElement.scrollHeight,
      docClientHeight: document.documentElement.clientHeight,
      bodyScrollHeight: document.body.scrollHeight,
      bodyClientHeight: document.body.clientHeight,
      chatMainOffsetHeight: chatMain.offsetHeight,
      canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight
    };
  });
  console.log('390x844 full height chat:', m390);

  // Test scrolling with mouse wheel / touch on 390
  await page.mouse.wheel(0, 200);
  await page.waitForTimeout(200);
  console.log('390 scrollY after wheel:', await page.evaluate(() => window.scrollY));

  await page.screenshot({ path: '/tmp/test_chat_fixed_390.png' });

  await browser.close();
})();
"

