const { chromium } = require('@playwright/test');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

  // 1. Start at /
  await page.goto('http://localhost:3000/');
  await page.waitForTimeout(500);
  console.log('Step 1 (Classic):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight
  })));

  // 2. Click Chat in switcher
  await page.getByRole('button', { name: 'Chat', exact: true }).click();
  await page.waitForSelector('text=Ask me anything about Sairam');
  await page.waitForTimeout(400);
  console.log('Step 2 (Switched to Chat):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight,
    scrollY: window.scrollY
  })));

  // 3. Click Classic in switcher
  await page.getByRole('button', { name: 'Classic', exact: true }).click();
  await page.waitForTimeout(400);
  console.log('Step 3 (Back to Classic):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight
  })));

  // 4. Click Dev in switcher
  await page.getByRole('button', { name: 'Dev', exact: true }).click();
  await page.waitForSelector('text=Query my work via the CLI');
  await page.waitForTimeout(400);
  console.log('Step 4 (Switched to Dev):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight,
    scrollY: window.scrollY
  })));

  // 5. Navigate to /resume
  await page.getByRole('link', { name: 'Résumé', exact: true }).first().click();
  await page.waitForURL('**/resume');
  await page.waitForTimeout(400);
  console.log('Step 5 (Navigated to /resume):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight
  })));

  // 6. Navigate back to /?view=chat
  await page.goto('http://localhost:3000/?view=chat');
  await page.waitForSelector('text=Ask me anything about Sairam');
  await page.waitForTimeout(400);
  console.log('Step 6 (Back to Chat):', await page.evaluate(() => ({
    fullHeight: document.documentElement.dataset.fullHeight,
    canScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    scrollHeight: document.documentElement.scrollHeight,
    clientHeight: document.documentElement.clientHeight,
    scrollY: window.scrollY
  })));

  await browser.close();
})();
"

